import requests
urls = [
'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/inchikey/XCLDEEZHMHGTLE-UHFFFAOYSA-N/property/IUPACName,Title,CanonicalSMILES/JSON',
'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term=%22XCLDEEZHMHGTLE%22&retmode=json',
'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term=%22COc1ccc(C2SC(=S)N%22&retmode=json'
]
for u in urls:
 try:
  r=requests.get(u,timeout=15); print('URL',u,'STATUS',r.status_code,'\n',r.text[:2000])
 except Exception as e: print(type(e).__name__,str(e))

import requests
s='COc1ccc(C2SC(=S)N(c3ccc(Cl)cc3)N2c2ccc(Cl)cc2)cc1'
u='https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/smiles/'+requests.utils.quote(s,safe='')+'/cids/JSON'
r=requests.get(u,timeout=20); print('PubChem lookup:',r.status_code,r.text[:500])
if r.ok and 'IdentifierList' in r.text:
 cids=r.json()['IdentifierList']['CID']; print('CIDs:',cids)
 for cid in cids[:3]:
  a=requests.get(f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/cid/{cid}/assaysummary/JSON',timeout=20)
  print('Assay summary',cid,a.status_code,a.text[:1000])
else: print('No structure-linked PubChem CID returned.')
